import React from 'react'

function Button({text}) {
    navigator = new navi
    function callURL(){
        window.location("https://en.wikipedia.org/wiki/Formation_and_evolution_of_the_Solar_System")
    }

  return (
    <div className=" justify-start flex">
            <a className=" text-white bg-purple-950 rounded-md w-3/12 h-12  " onClick={callURL} >
              {text}
            </a>
          </div>
  )
}

export default Button
